			inc hl
			ld (hl), d
			ret

;## kw_orvv
;kw_orvv, <var1>, <var2>, <destvar>
kw_orvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			or e
			ld e, a
			inc hl
			ld a, (hl)
			or d
			ld d, a
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## ntc_cmp
ntc_cmp_slt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ult:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sge:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_uge:
			ex de, hl
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_sgt:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ugt:
			or a
			sbc hl, de
			sbc a, a
			inc a
			ret
ntc_cmp_sle:
			ld a, d
			xor #80
			ld d, a
			ld a, h
			xor #80
			ld h, a
ntc_cmp_ule:
			or a
			sbc hl, de
			sbc a, a
			ret
ntc_cmp_eq:
			or a
			sbc hl, de
			ret
ntc_cmp_ne:
			or a
			sbc hl, de
			jr z, ntc_cmp_ne_f
			xor a
			ret
ntc_cmp_ne_f:
			or 1
			ret

;## kw_scpltvv ntc_cmp
;kw_scpltvv, <var1>, <var2>  - signed var1 < var2
kw_scpltvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_slt

;## kw_scpltvl ntc_cmp
;kw_scpltvl, <var>, <literal>
kw_scpltvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_slt

;## kw_scplevl ntc_cmp
kw_scplevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sle

;## kw_scpgtvv ntc_cmp
kw_scpgtvv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_sgt

;## kw_scpgtvl ntc_cmp
kw_scpgtvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sgt

;## kw_scpgevv ntc_cmp
kw_scpgevv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			jp ntc_cmp_sge

;## kw_scpgevl ntc_cmp
kw_scpgevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_sge

;## kw_cpeqvl ntc_cmp
kw_cpeqvl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_eq

;## kw_cpnevl ntc_cmp
kw_cpnevl:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			jp ntc_cmp_ne

; ============================================================
; Memory (PEEK / POKE / DEEK / DOKE)
; ============================================================

;## kw_aget
;kw_aget, <arraybase>, <indexvar>, <destvar>
kw_aget:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ld e, (hl)
			inc hl
			ld d, (hl)
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret

;## kw_aset
;kw_aset, <arraybase>, <indexvar>, <sourcevar>
kw_aset:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			ex de, hl
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			ex de, hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_asetl
;kw_asetl, <arraybase>, <indexvar>, <literal>
kw_asetl:
			pop de
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			add hl, hl
			add hl, de
			pop bc
			ld (hl), c
			inc hl
			ld (hl), b
			ret

; ============================================================
; Random (16 bit xorshift 7,9,8 - period 65535)
; ============================================================

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			pop de
ntc_rnd:
			ld hl, (ntc_rnd_seed)
			ld a, h
			rra
			ld a, l
			rra
			xor h
			ld h, a
			ld a, l
			rra
			ld a, h
			rra
			xor l
			ld l, a
			xor h
			ld h, a
			ld (ntc_rnd_seed), hl
			bit 7, d
			jr nz, ntc_rnd_zero
			ld a, d
			or e
			jr z, ntc_rnd_zero
			ld a, 1
			ld (ntc_mode), a
			res 7, h
			jp ntc_div
ntc_rnd_zero:
			ld hl, 0
			jp ntc_div_store

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			pop hl
			ld bc, 0
ntc_strlen_loop:
			ld a, (hl)
			or a
			jr z, ntc_strlen_done
			inc hl
			inc c
			jr ntc_strlen_loop
ntc_strlen_done:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_out
;kw_out, <portvar>, <valuevar>  - Out port, value: out (c), a with BC = port
kw_out:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld a, (hl)
			out (c), a
			ret

;## kw_frame ntc_data ntc_plat_frame
;kw_frame  - wait for the start of the next frame flyback
kw_frame:
			ld ix, ntc_next
			jp ntc_plat_frame

;## ntc_getn ntc_data
; BC = address of a word: A = its value limited to 0..255
; (below 0 = 0, above 255 = 255). jp (ix) back. Keeps DE, HL.
ntc_getn:
			ld a, (bc)
			ld (ntc_gnlo), a
			inc bc
			ld a, (bc)
			or a
			jp m, ntc_gn_zero
			jr nz, ntc_gn_max
			ld a, (ntc_gnlo)
			jp (ix)
ntc_gn_zero:
			xor a
			jp (ix)
ntc_gn_max:
			ld a, 255
			jp (ix)

;## kw_strleft ntc_getn
;kw_strleft, <dest>, <src>, <nvar>  - Left$(src, n)
kw_strleft:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sl_n
			jp ntc_getn
ntc_sl_n:
			ld b, a
; copy up to B chars from HL to DE, then the 0
ntc_strncpy:
			inc b
ntc_sn_loop:
			dec b
			jr z, ntc_sn_end
			ld a, (hl)
			or a
			jr z, ntc_sn_end
			ld (de), a
			inc hl
			inc de
			jr ntc_sn_loop
ntc_sn_end:
			xor a
			ld (de), a
			ret

;## kw_strmid ntc_getn kw_strleft
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sm_s
			jp ntc_getn
ntc_sm_s:
			or a
			jr z, ntc_sm_s1
			dec a
ntc_sm_s1:
			ld b, a
			inc b
ntc_sm_skip:
			dec b
			jr z, ntc_sm_len
			ld a, (hl)
			or a
			jr z, ntc_sm_len
			inc hl
			jr ntc_sm_skip
ntc_sm_len:
			pop bc
			ld ix, ntc_sm_n
			jp ntc_getn
ntc_sm_n:
			ld b, a
			jp ntc_strncpy

;## kw_strasc
;kw_strasc, <src>, <destvar>  - Asc(src), 0 if empty
kw_strasc:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## ntc_font
; 8x8 font buffer, chars 32-126, 8 bytes each, bit 7 = leftmost pixel.
; The platform fills it at start: the CPC copies its own font from the
; lower ROM (#3900), so text looks like the CPC's.
; glyph for char c = ntc_font + (c - 32) * 8
ntc_font:		ds 95 * 8

; ============================================================
; Platform class capabilities
; ============================================================

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based)
ntc_cury:		db 0			; cursor row (0 based)
ntc_smode:		db 1			; screen mode (0, 1: 40 columns, 2: 80)
ntc_sinit:		db 0			; 1 once the tilemap is set up
ntc_scols:		db 40			; columns
ntc_wrapped:	db 0			; 1 = the last character wrapped to the next line
ntc_klink:		dw 0			; return for ntc_plat_getkey
ntc_kidx:		db 0			; key index found by the scan
ntc_kcur:		ds 8			; the 8 half rows this scan (0 = pressed)
ntc_kprev:		db #FF, #FF, #FF, #FF, #FF, #FF, #FF, #FF
ntc_irqset:		db 0			; 1 = our interrupt handler is at #38
ntc_irqold:		ds 3			; the 3 bytes it replaced
ntc_irqhl:		dw 0			; handler scratch
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_zxvs:		db 0			; 1: this interrupt is a frame's first (line 0: to ntc_isl_tick in C)
ntc_zxline:		dw 0			; the raster line the line interrupt is set to
ntc_zxsel:		db 0			; the NextReg selected (#243B) by code interrupts can get into: the
								; handler selects it again after its own (store it, then select)
ntc_zxl2:		db 0			; 1 = Layer 2 is on (Graphics); Mode turns it off
ZXN_MAP			equ #E000		; the tilemap (bank 5 + #2000: NextReg #6E = #20)
ZXN_TILES		equ #EC00		; its characters (bank 5 + #2C00: NextReg #6F = #2C)
ZXN_ROWS		equ 32
ZXN_PAPER		equ #02			; RRRGGGBB: blue
ZXN_INK			equ #FC			; yellow

;## ntc_plat_screen ntc_plat_data ntc_font ntc_data ntc_plat_scroll @shared
; ------------------------------------------------------------
; ntc_plat_putc - A = character 32-126 (others print as ?), draw it
; ------------------------------------------------------------
ntc_plat_putc:
			cp 32
			jr c, ntc_pc_bad
			cp 127
			jr c, ntc_zx_put
ntc_pc_bad:
			ld a, '?'
			jr ntc_zx_put

; ------------------------------------------------------------
; ntc_plat_putglyph - DE = an 8 byte glyph in ntc_font (ZOSCII text): that
; character at the cursor, the cursor on (a glyph not in ntc_font: ?)
; ------------------------------------------------------------
ntc_plat_putglyph:
			ld hl, -ntc_font
			add hl, de				; HL = the glyph's offset: 0 .. 95 * 8 - 1
			ld a, h
			cp (95 * 8) / 256
			jr c, ntc_pg_in
			jr nz, ntc_pc_bad
			ld a, l
			cp (95 * 8) & 255
			jr nc, ntc_pc_bad
ntc_pg_in:
			srl h
			rr l
			srl h
			rr l
			srl h
			rr l
			ld a, l
			add a, 32
			; fall into ntc_zx_put

; A = a character code: into the tilemap at the cursor (its tile), the cursor on
ntc_zx_put:
			ld c, a
			ld a, (ntc_cury)		; HL = ZXN_MAP + row * columns + column
			ld l, a
			ld h, 0
			add hl, hl
			add hl, hl
			add hl, hl
			ld d, h
			ld e, l
			add hl, hl
			add hl, hl
			add hl, de				; row * 40
			ld a, (ntc_scols)
			cp 80
			jr nz, $+3
			add hl, hl				; row * 80
			ld a, (ntc_curx)
			ld e, a
			ld d, ZXN_MAP / 256		; (ZXN_MAP's low byte is 0)
			add hl, de
			ld (hl), c
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr z, ntc_pg_wrap
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_pg_wrap:
			ld a, 1				; wrapped: a new line straight after does nothing
			ld (ntc_wrapped), a
			jr ntc_nl_do

; ------------------------------------------------------------
; ntc_plat_newline - column 0, next row, scroll at the bottom. Straight
; after a wrap at the last column it does nothing (as the firmware does)
; ------------------------------------------------------------
ntc_plat_newline:
			ld a, (ntc_wrapped)
			or a
			jr z, ntc_nl_do
			xor a
			ld (ntc_wrapped), a
			jp (ix)
ntc_nl_do:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp ZXN_ROWS
			jp nc, ntc_plat_scroll
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_scroll ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_scroll - move rows 1-31 up one, clear row 31
; ------------------------------------------------------------
ntc_plat_scroll:
			ld a, ZXN_ROWS - 1
			ld (ntc_cury), a
			ld a, (ntc_scols)
			ld c, a
			ld b, 0					; BC = a row
			ld hl, ZXN_MAP
			add hl, bc
			ld de, ZXN_MAP
			cp 80
			ld bc, (ZXN_ROWS - 1) * 40
			jr nz, ntc_sc_40
			ld bc, (ZXN_ROWS - 1) * 80
ntc_sc_40:
			ldir					; DE = the last row
			ld h, d
			ld l, e
			ld (hl), ' '
			inc de
			ld c, a
			dec c
			ld b, 0
			ldir
			jp (ix)

; ------------------------------------------------------------
; ntc_plat_cls - the whole tilemap spaces, cursor home
; ------------------------------------------------------------
ntc_plat_cls:
			ld hl, ZXN_MAP
			ld de, ZXN_MAP + 1
			ld bc, ZXN_ROWS * 80 - 1
			ld (hl), ' '
			ldir
			xor a
			ld (ntc_wrapped), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			jp (ix)

;## ntc_plat_frame ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_plat_frame - wait for the end of the display (raster line 192: the
; bottom border starts). Normal mode: interrupts in while waiting
; ------------------------------------------------------------
ntc_plat_frame:
			ld (ntc_klink), ix		; (ntc_klink: the return - IX runs ntc_fr_line)
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_go
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
ntc_fr_go:
			ld bc, #243B
ntc_fr_out:						; first out of lines 192 and on (the border, the sync)
			ld ix, ntc_fr_out2
			jr ntc_fr_line
ntc_fr_out2:
			jr nz, ntc_fr_out
ntc_fr_in:						; then wait for line 192
			ld ix, ntc_fr_in2
			jr ntc_fr_line
ntc_fr_in2:
			jr z, ntc_fr_in
			jr ntc_fr_at
; the raster line (NextReg #1E: its bit 8, #1F: bits 0-7), its two halves read
; again until bit 8 is the same both times (line 255 to 256 between them reads
; as 0): NZ = line 192 or more. Back to IX; keeps BC (#243B)
ntc_fr_line:
			ld a, #1E
			ld (ntc_zxsel), a		; (interrupts are in: the handler selects it again)
			out (c), a
			inc b
			in d, (c)
			dec b
			ld a, #1F
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in e, (c)
			dec b
			ld a, #1E
			ld (ntc_zxsel), a
			out (c), a
			inc b
			in a, (c)
			dec b
			cp d
			jr nz, ntc_fr_line
			rra
			jr c, ntc_fr_lnz		; 256 and on
			ld a, e
			cp 192
			ccf
			sbc a, a				; #FF: 192-255, 0: below
			jp (ix)
ntc_fr_lnz:
			or 1
			jp (ix)
ntc_fr_at:
			di
			ld a, (ntc_nmode)
			or a
			jr z, ntc_fr_done
			ld sp, (ntc_ip)
ntc_fr_done:
			ld ix, (ntc_klink)
			jp (ix)

;## ntc_plat_exit ntc_plat_data
; ------------------------------------------------------------
; ntc_plat_exit - the end: interrupts off, a soft reset (NextReg 2 bit 0) -
; back to NextZXOS (a NEX file has no caller to return to)
; ------------------------------------------------------------
ntc_plat_exit:
			di
			ld bc, #243B
			ld a, #02
			out (c), a
			inc b
			ld a, 1
			out (c), a
ntc_ex_wait:
			jr ntc_ex_wait

;## ntc_plat_memtop
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #BE00 (the stack is above, to #C000). Called on the real stack
; (call / ret), only by the Memory class.
ntc_plat_memtop:
			ld hl, #BE00
			ret


ntc_rsvtab:				; Option Reserve starts (the Memory class's heap stops at them), 0 ends
			dw 0

ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_wx		equ ntc_bss + 0		; 16 bytes
arr_wy		equ ntc_bss + 16		; 16 bytes
arr_wz		equ ntc_bss + 32		; 16 bytes
arr_ws		equ ntc_bss + 48		; 16 bytes
arr_wr		equ ntc_bss + 64		; 16 bytes
arr_e3_pvx		equ ntc_bss + 80		; 96 bytes
arr_e3_pvy		equ ntc_bss + 176		; 96 bytes
arr_e3_cm		equ ntc_bss + 272		; 18 bytes
arr_e3_cp		equ ntc_bss + 290		; 12 bytes
arr_e3_sun		equ ntc_bss + 302		; 6 bytes
arr_e3_op		equ ntc_bss + 308		; 6 bytes
arr_e3_oc		equ ntc_bss + 314		; 6 bytes
arr_e3_obj		equ ntc_bss + 320		; 1024 bytes
arr_e3_ppos		equ ntc_bss + 1344		; 6 bytes
arr_e3_aimp		equ ntc_bss + 1350		; 6 bytes
arr_e3_aimv		equ ntc_bss + 1356		; 6 bytes
arr_e3_pup		equ ntc_bss + 1362		; 6 bytes
arr_e3_suc		equ ntc_bss + 1368		; 6 bytes
arr_e3_od		equ ntc_bss + 1374		; 6 bytes
arr_e3_ccl		equ ntc_bss + 1380		; 18 bytes
arr_e3_oe		equ ntc_bss + 1398		; 6 bytes
arr_e3_osn		equ ntc_bss + 1404		; 6 bytes
arr_e3_ov		equ ntc_bss + 1410		; 384 bytes
arr_e3_osx		equ ntc_bss + 1794		; 128 bytes
arr_e3_osy		equ ntc_bss + 1922		; 128 bytes
arr_e3_cla		equ ntc_bss + 2050		; 288 bytes
arr_e3_clb		equ ntc_bss + 2338		; 288 bytes
ntc_bss_size	equ 2626
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables

; ============================================================
; ZX Spectrum Next: the start stub (bank 5, page 11 at #7E00) and the NEX file
; ============================================================
			ASSERT ntc_free <= #BE00, "the program and its arrays must end below #BE00 (the stack is #BE00-#BFFF, the screen #C000-#FFFF)"
			MMU 3, 11			; page 11 (bank 5's second half) at #6000 to assemble the stub
			org #7E00
zxn_boot:
			di
			ld bc, #243B		; NextReg select (#253B: its value)
			ld a, 6			; Peripheral 2: the NMI buttons off (bit 3 Multiface M1, bit 4 DivMMC DRIVE)
			out (c), a
			inc b
			in a, (c)
			and %11100111
			out (c), a
			dec b
			ld a, 10			; Peripheral 5: DivMMC automatic paging off (bit 4)
			out (c), a
			inc b
			in a, (c)
			and %11101111
			out (c), a
			dec b
			xor a
			out (#E3), a		; DivMMC: its memory out
			ld a, 7			; CPU speed: 28MHz
			out (c), a
			inc b
			ld a, 3
			out (c), a
			dec b
			ld hl, zxn_mmu		; the slots but 3
			ld e, 7
zxn_bmmu:
			ld a, (hl)
			inc hl
			out (c), a
			inc b
			ld a, (hl)
			inc hl
			out (c), a
			dec b
			dec e
			jr nz, zxn_bmmu
			jp zxn_boot2 + #8000	; on in the copy at #E000-#FFFF (page 11 in slot 7)
zxn_boot2:
			ld a, #53			; slot 3: page 19
			out (c), a
			inc b
			ld a, 19
			out (c), a
			ld hl, #C9FB		; #0038: ei, ret until ntc_plat_irqon puts its jump there
			ld (#0038), hl
			im 1
			jp ntc_start
zxn_mmu:	db #50, 16, #51, 17, #52, 18, #54, 20, #55, 21, #56, 10, #57, 11
			SAVENEX OPEN "POLY.NEX", zxn_boot, #BFFE
			SAVENEX CORE 3, 0, 0
			SAVENEX CFG 0
			SAVENEX BANK 5, 8, 9, 10
			SAVENEX CLOSE